#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long double A, B, C;
    if(!(cin >> A >> B >> C)) return 0;

    const long double EPS = 1e-12L;
    if (fabsl(A) < EPS && fabsl(B) < EPS && fabsl(C) < EPS) {
        cout << -1 << "\n";
        return 0;
    }
    if (fabsl(A) < EPS && fabsl(B) < EPS) {
        cout << 0 << "\n";
        return 0;
    }

    cout.setf(std::ios::fixed);
    cout << setprecision(10);

    if (fabsl(A) < EPS) {
        // Linear case: Bx + C = 0
        long double x = -C / B;
        if (fabsl(x) < EPS) x = 0.0L;
        cout << 1 << "\n" << x << "\n";
        return 0;
    }

    long double D = B*B - 4*A*C;
    if (D < -EPS) {
        cout << 0 << "\n";
        return 0;
