    long double sqrtD = sqrt((long double)D);
    long double x1 = (-B - sqrtD) / (2*A);
    long double x2 = (-B + sqrtD) / (2*A);
    vector<long double> roots = {x1, x2};
    for (auto &r : roots) if (fabsl(r) < EPS) r = 0;
    sort(roots.begin(), roots.end());

    cout << 2 << "\n" << roots[0] << "\n" << roots[1] << "\n";
    return 0;
}
