import sys

def count_ways(n, a, b, c):
    target = 2 * n
    ans = 0
    maxz = min(c, n // 2)
    def ceil_div(x, y):
        return -((-x) // y)
    for z in range(maxz + 1):
        R = target - 4 * z
        # y_min = ceil((R - a) / 2) bounded below by 0
        y_min = max(0, ceil_div(R - a, 2))
        y_max = min(b, R // 2)
        if y_min <= y_max:
            ans += (y_max - y_min + 1)
    return ans

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0]); a = int(data[1]); b = int(data[2]); c = int(data[3])
    print(count_ways(n, a, b, c))

if __name__ == "__main__":
