import sys


def solve_line(line):
    tokens = line.strip().split()
    eqi = None
    for i, tk in enumerate(tokens):
        if tk == '=':
            eqi = i
            break
    if eqi is None:
        return None
    target = int(tokens[eqi+1])
    k = eqi // 2 + 1
    sign = [0]*k
    sign[0] = 1
    for i in range(1, k):
        sign[i] = 1 if tokens[2*i - 1] == '+' else -1
    arr = [0]*k
    arr[0] = 1
    for i in range(1, k):
        arr[i] = 1 if sign[i] == 1 else target
    p = sum(1 for s in sign if s == 1)
    m = k - p
    current = arr[0] + sum(sign[i]*arr[i] for i in range(1, k))
    maxTotal = p*target - m
    if current > target or target > maxTotal:
        return None
    diff = target - current
    for i in range(k):
        if sign[i] == 1:
            can = target - arr[i]
            if can > 0:
                t = diff if diff < can else can
                arr[i] += t
                diff -= t
                if diff == 0:
                    break
    if diff > 0:
        for i in range(k):
            if sign[i] == -1:
                can = arr[i] - 1
                if can > 0:
                    t = diff if diff < can else can
                    arr[i] -= t
                    diff -= t
                    if diff == 0:
                        break
    if diff > 0:
        return None
    s = [str(arr[0])]
    for i in range(1, k):
        s.append('+' if sign[i] == 1 else '-')
        s.append(str(arr[i]))
    expr = ' '.join(s) + ' = ' + str(target)
    return ("Possible", expr)


def main():
