import sys
from collections import deque


def has_2x2(state, M, N):
    # Check if any 2x2 block is all ones in the given state
    for i in range(M - 1):
        for j in range(N - 1):
            idx = i * N + j
            b1 = (state >> idx) & 1
            b2 = (state >> ((i + 1) * N + j)) & 1
            b3 = (state >> (i * N + (j + 1))) & 1
            b4 = (state >> ((i + 1) * N + (j + 1))) & 1
            if b1 and b2 and b3 and b4:
                return True
    return False


def generate_rect_masks(M, N):
    masks = []
    for r1 in range(M):
        for c1 in range(N):
            for r2 in range(r1, M):
                for c2 in range(c1, N):
                    h = r2 - r1 + 1
                    w = c2 - c1 + 1
                    if h * w <= 1:
                        continue  # ignore 1x1 rectangles
                    mask = 0
                    for i in range(r1, r2 + 1):
                        for j in range(c1, c2 + 1):
                            pos = i * N + j
                            mask |= (1 << pos)
                    masks.append(mask)
    return masks


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    M = int(next(it))
    N = int(next(it))
    A = []
    for _ in range(M):
        row = [int(next(it)) for _ in range(N)]
        A.append(row)

    # initial state bitmask
    state = 0
    for i in range(M):
        for j in range(N):
            if A[i][j] == 1:
                state |= (1 << (i * N + j))

    # early check: if initial state already has a 2x2 all-ones block
    if has_2x2(state, M, N):
