        return

    masks = generate_rect_masks(M, N)
    q = deque()
    visited = set()
    q.append((state, 0))
    visited.add(state)

    # Guard to avoid pathological cases on large inputs
    max_states = 200000

    while q:
        s, d = q.popleft()
        if len(visited) > max_states:
