#!/usr/bin/env python3
import sys
from bisect import bisect_right

class PiecewiseFunction:
    def __init__(self, X):
        self.X = X
        # segments: list of (L, R, s, b) representing f(a) = s*a + b on [L, R)
        self.segs = [(0, X, 1, 0)]  # initial f(a) = a on [0, X)
        self._rebuild_Ls()

    def _rebuild_Ls(self):
        self.Ls = [seg[0] for seg in self.segs]

    def evaluate(self, a):
        # find segment containing a
        idx = bisect_right(self.Ls, a) - 1
        if idx < 0:
            idx = 0
        L, R, s, b = self.segs[idx]
        return s * a + b

    def _merge(self):
        merged = []
        for (L, R, s, b) in self.segs:
            if not merged:
                merged.append([L, R, s, b])
            else:
                PL, PR, PS, PB = merged[-1]
                if L == PR and PS == s and PB == b:
                    merged[-1][1] = R  # extend previous segment
                else:
                    merged.append([L, R, s, b])
        self.segs = [tuple(x) for x in merged]
        self._rebuild_Ls()

    def update_odd(self, Delta):
        # h(a) = max(f(a) - Delta, 0)
        new = []
        for (L, R, s, b) in self.segs:
            if s == 0:
                y = b
                if y >= Delta:
                    new.append((L, R, 0, b - Delta))
                else:
                    new.append((L, R, 0, 0))
            else:  # s == 1
                a0 = Delta - b  # threshold where f(a) = a + b crosses Delta
                if a0 <= L:
                    new.append((L, R, 1, b - Delta))
                elif a0 >= R:
                    new.append((L, R, 0, 0))
                else:
                    new.append((L, a0, 0, 0))
                    new.append((a0, R, 1, b - Delta))
        self.segs = new
        self._merge()

    def update_even(self, Delta):
        # h("a") = min(f(a) + Delta, X)
        new = []
        X = self.X
        for (L, R, s, b) in self.segs:
            if s == 0:
                y = b
                if y + Delta <= X:
                    new.append((L, R, 0, b + Delta))
                else:
                    new.append((L, R, 0, X))
            else:  # s == 1
                a_sat = X - Delta - b
                if a_sat <= L:
                    new.append((L, R, 0, X))
                elif a_sat >= R:
                    new.append((L, R, 1, b + Delta))
                else:
                    new.append((L, a_sat, 1, b + Delta))
                    new.append((a_sat, R, 0, X))
        self.segs = new
        self._merge()


def main():
