        r.append(int(next(it)))
    Q = int(next(it))
    queries = []
    for _ in range(Q):
        t = int(next(it)); a = int(next(it))
        queries.append((t, a))

    f = PiecewiseFunction(X)
    m = 0  # number of complete intervals processed
    out_lines = []

    for t, a in queries:
        # advance through complete intervals while t >= next flip time
        while m < K and t >= r[m+1]:
            Delta = r[m+1] - r[m]
            if ((m+1) % 2) == 1:
                f.update_odd(Delta)
            else:
