            else:  # s == 1
                a0 = Delta - b  # threshold where f(a) = a + b crosses Delta
                if a0 <= L:
                    new.append((L, R, 1, b - Delta))
                elif a0 >= R:
                    new.append((L, R, 0, 0))
                else:
                    new.append((L, a0, 0, 0))
                    new.append((a0, R, 1, b - Delta))
        self.segs = new
        self._merge()

    def update_even(self, Delta):
        # h(a) = min(f(a) + Delta, X)
        new = []
        for (L, R, s, b) in self.segs:
            if s == 0:
                y = b
                if y + Delta <= self.X:
                    new.append((L, R, 0, b + Delta))
                else:
                    new.append((L, R, 0, self.X))
            else:  # s == 1
                a_sat = self.X - Delta - b
                if a_sat <= L:
                    new.append((L, R, 0, self.X))
                elif a_sat >= R:
                    new.append((L, R, 1, b + Delta))
                else:
                    new.append((L, a_sat, 1, b + Delta))
                    new.append((a_sat, R, 0, self.X))
        self.segs = new
        self._merge()


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    X = int(next(it))
    K = int(next(it))
    r = [0]
    for _ in range(K):
        r.append(int(next(it)))
    Q = int(next(it))
    queries = []
    for _ in range(Q):
        t = int(next(it)); a = int(next(it))
        queries.append((t, a))

    f = PiecewiseFunction(X)
    m = 0  # number of complete intervals processed
    out_lines = []

    for t, a in queries:
        while m < K and t >= r[m+1]:
            Delta = r[m+1] - r[m]
            if ((m+1) % 2) == 1:
                f.update_odd(Delta)
            else:
                f.update_even(Delta)
            m += 1
        delta = t - r[m]
        A_prev = f.evaluate(a)
        if ((m+1) % 2) == 1:
            val = A_prev - delta
            if val < 0:
                val = 0
        else:
            val = A_prev + delta
            if val > X:
                val = X
        out_lines.append(str(val))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
