#!/usr/bin/env python3
import sys


def parse(line):
  parts = [p.strip() for p in line.strip().split(',')]
  if len(parts) != 8:
    return None
  pts = [(float(parts[i]), float(parts[i+1])) for i in range(0, 8, 2)]
  return pts


def cross(o, a, b):
  return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])


def is_convex(pts):
  A, B, C, D = pts
  s1 = cross(A, B, C)
  s2 = cross(B, C, D)
  s3 = cross(C, D, A)
  s4 = cross(D, A, B)
  eps = 1e-9
  signs = []
  for s in (s1, s2, s3, s4):
    if s > eps:
      signs.append(1)
    elif s < -eps:
      signs.append(-1)
    else:
      signs.append(0)
  if 0 in signs:
    return False
  return ((signs[0] > 0 and signs[1] > 0 and signs[2] > 0 and signs[3] > 0) or
