    int n = (int)A.size();
    for (int i = 0; i < n; ++i) {
        int piv = i;
        for (int r = i + 1; r < n; ++r) {
            if (fabs(A[r][i]) > fabs(A[piv][i])) piv = r;
        }
        if (fabs(A[piv][i]) < 1e-12) continue; // assume non-singular in valid inputs
        swap(A[i], A[piv]);
        swap(b[i], b[piv]);
        // Eliminate
        for (int r = i + 1; r < n; ++r) {
            double f = A[r][i] / A[i][i];
            if (fabs(f) < 1e-18) continue;
            for (int c = i; c < n; ++c) A[r][c] -= f * A[i][c];
            b[r] -= f * b[i];
        }
    }
    vector<double> x(n, 0.0);
    for (int i = n - 1; i >= 0; --i) {
        double s = b[i];
        for (int j = i + 1; j < n; ++j) s -= A[i][j] * x[j];
        if (fabs(A[i][i]) > 1e-12) x[i] = s / A[i][i];
        else x[i] = 0.0; // should not happen for valid inputs
    }
    return x;
}

struct Edge { int to, rev, cap; double cost; };
struct MinCostMaxFlow {
    int N; vector<vector<Edge>> G;
    MinCostMaxFlow(int n=0){ init(n); }
    void init(int n){ N=n; G.assign(n,{}); }
    void addEdge(int u, int v, int cap, double cost){
        Edge a{v, (int)G[v].size(), cap, cost};
        Edge b{u, (int)G[u].size(), 0, -cost};
        G[u].push_back(a);
        G[v].push_back(b);
    }
    pair<int,double> minCostMaxFlow(int s, int t, int maxf){
        int flow = 0;
        double cost = 0.0;
        const double INF = 1e100;
        vector<double> pot(N, 0.0), dist(N);
        vector<int> pv(N), pe(N);
        while (flow < maxf){
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0.0;
            using PDI = pair<double,int>;
            priority_queue<PDI, vector<PDI>, greater<PDI>> pq;
            pq.push({0.0, s});
            while (!pq.empty()){
                auto [d,u] = pq.top(); pq.pop();
                if (d > dist[u] + 1e-15) continue;
                for (int i = 0; i < (int)G[u].size(); ++i){
                    Edge &e = G[u][i];
                    if (e.cap <= 0) continue;
                    int v = e.to;
                    double nd = dist[u] + e.cost + pot[u] - pot[v];
                    if (nd + 1e-15 < dist[v]){
                        dist[v] = nd; pv[v] = u; pe[v] = i; pq.push({nd, v});
                    }
                }
            }
            if (dist[t] >= INF/2) break; // cannot send more
            for (int i = 0; i < N; ++i) if (dist[i] < INF) pot[i] += dist[i];
            int addf = maxf - flow;
            int v = t;
            while (v != s){
                int u = pv[v];
                Edge &e = G[u][pe[v]];
                addf = min(addf, e.cap);
                v = u;
            }
            double pathcost = 0.0;
            v = t;
            while (v != s){
                int u = pv[v];
                Edge &e = G[u][pe[v]];
                pathcost += e.cost;
                v = u;
            }
            v = t;
            while (v != s){
                int u = pv[v];
                Edge &e = G[u][pe[v]];
                e.cap -= addf;
                G[v][e.rev].cap += addf;
                v = u;
            }
            flow += addf;
            cost += addf * pathcost;
        }
        return {flow, cost};
    }
};

int main(){
  ios::sync_with_stdio(false); cin.tie(nullptr);
  int T; if(!(cin>>T)) return 0;
  cout.setf(std::ios::fixed); cout<<setprecision(10);
  while(T--){
    int N, s, t, F; 
    if(!(cin>>N>>s>>t>>F)) break;
    vector<vector<double>> A(N, vector<double>(N));
    vector<double> b(N);
    for (int i = 0; i < N; ++i){
      for (int j = 0; j < N; ++j){ int v; cin >> v; A[i][j] = (double)v; }
      double ci; cin >> ci; b[i] = ci;
    }
    vector<double> temps = solveLinear(A, b);
    MinCostMaxFlow mcmf(N);
    for (int i = 0; i < N; ++i){
      int Mi; cin >> Mi;
      vector<int> d(Mi);
      for (int j = 0; j < Mi; ++j) cin >> d[j];
      vector<int> f(Mi);
      for (int j = 0; j < Mi; ++j) cin >> f[j];
      for (int j = 0; j < Mi; ++j){
        int to = d[j]; int cap = f[j];
        double cost = fabs(temps[i] - temps[to]);
        mcmf.addEdge(i, to, cap, cost);
      }
    }
    auto res = mcmf.minCostMaxFlow(s, t, F);
    if (res.first < F) cout << "impossible\n";
    else cout << res.second << "\n";
  }
  return 0;
}
