# Python solution for Nearest Station
import sys

def pow_cap(base, exp, cap):
    # computes base**exp, but if it exceeds cap, returns cap+1
    if cap < 0:
        return cap
    res = 1
    b = base
    e = exp
    while e > 0:
        if e & 1:
            res *= b
            if res > cap:
                return cap + 1
        e >>= 1
        if e:
            b *= b
            if b > cap:
                b = cap + 1
    return res


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, a, b, p, q = map(int, data[:6])

    # Special case: both bases 1 -> constant s_k
    if a == 1 and b == 1:
        print(n)
        return

    def s_k_leq_m(k):
        A = pow_cap(a, k, m)
        if A > m:
            return False
        B = pow_cap(b, k, m)
        if B > m:
            return False
        s = p * A + q * B
        return s <= m

    # Binary search for largest k such that s_k <= m
    lo = 0
    hi = n - 1
    k_max = -1
    s0 = p * 1 + q * 1
    if s0 <= m:
        while lo <= hi:
            mid = (lo + hi) // 2
            if s_k_leq_m(mid):
                k_max = mid
                lo = mid + 1
            else:
                hi = mid - 1

    # Prepare candidate k values
    candidates = []
    if k_max >= 0:
        candidates.append(k_max)
        k2 = k_max + 1
        if k2 <= n - 1:
            candidates.append(k2)
    else:
        candidates = [0]

    def s_k(k):
        A = pow_cap(a, k, m)
        if A > m:
            return m + 1
        B = pow_cap(b, k, m)
        if B > m:
            return m + 1
        return p * A + q * B

    best = None
    count = 0
    for k in sorted(set(candidates)):
        val = s_k(k)
        dist = abs(m - val)
        if best is None or dist < best:
            best = dist
            count = 1
        elif dist == best:
            count += 1

    if count == 0:
        # Fallback (shouldn't usually happen)
        val = s_k(0)
        dist = abs(m - val)
        best = dist
        count = 1

    print(count)

if __name__ == '__main__':
    solve()
