        // condensation indegree
        vector<int> indegDag(C,0);
        for(int u=0; u<C; ++u) for(int v: dag[u]) indegDag[v]++;
        int rootCnt = 0, root = -1;
        for(int c=0;c<C;c++) if(indegDag[c]==0){ rootCnt++; root=c; }
        if(rootCnt != 1){ cout << -1 << "\n"; continue; }
