        vector<char> visDag(C,false);
        vector<int> stackv; stackv.push_back(root); visDag[root] = true;
        for(size_t i=0; i<stackv.size(); ++i){
            int u = stackv[i];
            for(int v: dag[u]) if(!visDag[v]){ visDag[v] = true; stackv.push_back(v); }
        }
        bool allReachable = true; for(int c=0;c<C;c++) if(!visDag[c]) { allReachable = false; break; }
        if(!allReachable){ cout << -1 << "\n"; continue; }
        bool treeProp = true; for(int c=0;c<C;c++) if(c!=root && indegDag[c] != 1){ treeProp = false; break; }
        if(!treeProp){ cout << -1 << "\n"; continue; }
        // collect vertices from root component
        vector<int> ans = nodesInComp[root]; sort(ans.begin(), ans.end());
        int k = (int)ans.size();
        if((long long)k * 5 < n){ cout << -1 << "\n"; continue; }
        for(int i=0;i<k;i++){ if(i) cout << ' '; cout << ans[i] + 1; }
        cout << "\n";
    }
    return 0;
}
