#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; if(!(cin>>t)) return 0;
    while(t--){
        int n,m; cin>>n>>m;
        vector<vector<int>> g(n), gr(n);
        vector<pair<int,int>> edges; edges.reserve(m);
        for(int i=0;i<m;i++){
            int u,v; cin>>u>>v; --u; --v;
            g[u].push_back(v);
            gr[v].push_back(u);
            edges.emplace_back(u,v);
        }
        // 1) Kosaraju - first pass: finishing order (iterative)
        vector<char> vis(n,false);
        vector<int> order; order.reserve(n);
        for(int i=0;i<n;i++) if(!vis[i]){
            stack<pair<int,int>> st; st.push({i,0}); vis[i]=true;
            while(!st.empty()){
                int u = st.top().first;
                int &idx = st.top().second;
                if(idx < (int)g[u].size()){
                    int w = g[u][idx++];
                    if(!vis[w]){ vis[w]=true; st.push({w,0}); }
                } else {
                    order.push_back(u);
                    st.pop();
                }
            }
        }
        // 2) Kosaraju - second pass: assign components on reversed graph
        vector<int> comp(n,-1);
        int C=0;
        for(int i=n-1;i>=0;--i){
            int v = order[i];
            if(comp[v]==-1){
                stack<int> st; st.push(v); comp[v]=C;
                while(!st.empty()){
                    int u = st.top(); st.pop();
                    for(int w: gr[u]) if(comp[w]==-1){ comp[w]=C; st.push(w); }
                }
                ++C;
            }
        }
        vector<vector<int>> nodesInComp(C);
        for(int i=0;i<n;i++) nodesInComp[comp[i]].push_back(i);
        // Track internal outgoing per node
        vector<int> internalOut(n,0);
        for(auto &e: edges){
            int a=e.first, b=e.second;
            if(comp[a]==comp[b]) internalOut[a]++;
        }
        // Build condensation DAG
        vector<vector<int>> dag(C);
        for(auto &e: edges){
            int a=e.first, b=e.second; int ca=comp[a], cb=comp[b];
            if(ca!=cb) dag[ca].push_back(cb);
        }
        // deduplicate DAG edges
        for(int i=0;i<C;i++){
            auto &v = dag[i]; if(v.size()>1){ sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end()); }
        }
        // compute in-degrees in DAG
        vector<int> indegDag(C,0);
        for(int u=0; u<C; ++u) for(int v: dag[u]) indegDag[v]++;
        // roots in DAG
        vector<int> roots; for(int i=0;i<C;i++) if(indegDag[i]==0) roots.push_back(i);
        if((int)roots.size()!=1){ cout << -1 << "\n"; continue; }
        int root = roots[0];
        // reachability from root in DAG
        vector<char> visDag(C,false); visDag[root]=true; vector<int> q; q.push_back(root);
        for(size_t qi=0; qi<q.size(); ++qi){ int u=q[qi]; for(int v: dag[u]) if(!visDag[v]){ visDag[v]=true; q.push_back(v); } }
        bool allReachable = true; for(int i=0;i<C;i++) if(!visDag[i]){ allReachable=false; break; }
        if(!allReachable){ cout << -1 << "\n"; continue; }
        // tree property: every non-root component has indegree 1
        bool treeProp = true; for(int i=0;i<C;i++) if(i!=root && indegDag[i]!=1){ treeProp = false; break; }
        if(!treeProp){ cout << -1 << "\n"; continue; }
        // internal SCC check: each component with size>1 must be a simple directed cycle
        bool okAll = true;
        for(int c=0;c<C && okAll;c++){
            int sz = (int)nodesInComp[c].size();
            if(sz <= 1) continue; // single vertex ok
            // all nodes in this comp must have exactly one internal outgoing edge
            for(int u: nodesInComp[c]){
                if(internalOut[u] != 1){ okAll = false; break; }
            }
        }
        if(!okAll){ cout << -1 << "\n"; continue; }
        // collect vertices from root component
        auto &rootNodes = nodesInComp[root]; sort(rootNodes.begin(), rootNodes.end());
        int k = (int)rootNodes.size();
        if((long long)k * 5 < n){ cout << -1 << "\n"; continue; }
        for(int i=0;i<k;i++){ if(i) cout << ' '; cout << rootNodes[i] + 1; }
        cout << "\n";
    }
    return 0;
}

