import sys
from collections import Counter


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    k = int(data[0])
    s = data[1]
    freq = Counter(s)
    for v in freq.values():
        if v % k != 0:
            print(-1)
            return
    parts = []
    for ch in sorted(freq.keys()):
        cnt = freq[ch] // k
        if cnt:
            parts.append(ch * cnt)
    t = ''.join(parts)
    print(t * k)


if __name__ == '__main__':
    main()
