#include <bits/stdc++.h>
using namespace std;

struct DSU {
    int n;
    vector<int> p, r;
    DSU(int n=0): n(n), p(n), r(n,0) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x){
        if(p[x]==x) return x;
        return p[x]=find(p[x]);
    }
    void unite(int a, int b){
        a = find(a); b = find(b);
        if(a==b) return;
        if(r[a] < r[b]) swap(a,b);
        p[b] = a;
        if(r[a] == r[b]) r[a]++;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if(!(cin >> n >> m)) return 0;
    vector<int> p(n);
    for(int i=0; i<n; ++i) cin >> p[i];
    DSU dsu(n);
    for(int i=0; i<m; ++i){
        int a,b; cin >> a >> b; --a; --b;
        dsu.unite(a,b);
    }
    vector<int> comp_root_id(n, -1);
    int comp_cnt = 0;
    for(int i=0; i<n; ++i){
        int r = dsu.find(i);
        if(comp_root_id[r] == -1){
            comp_root_id[r] = comp_cnt++;
        }
    }
    vector<vector<int>> comp_indices(comp_cnt);
    vector<vector<int>> comp_values(comp_cnt);
    for(int i=0; i<n; ++i){
        int r = dsu.find(i);
        int cid = comp_root_id[r];
        comp_indices[cid].push_back(i);
        comp_values[cid].push_back(p[i]);
    }
    vector<int> ans(n);
    for(int cid=0; cid<comp_cnt; ++cid){
        auto &idx = comp_indices[cid];
        auto &vals = comp_values[cid];
        sort(idx.begin(), idx.end());
        sort(vals.begin(), vals.end(), greater<int>());
        for(size_t k=0; k<idx.size(); ++k){
            ans[idx[k]] = vals[k];
        }
    }
    for(int i=0; i<n; ++i){
        if(i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}
