#!/usr/bin/env python3
import time
import os
import sys
from multiprocessing import Process, Queue, cpu_count
from threading import Thread, Event


def worker_loop(q):
    while True:
        path = q.get()
        if path is None:
            break
        print(f"[Worker {os.getpid()}] Processing: {path}")
        # simulate some work
        time.sleep(0.25)


def poll_dir(path, q, stop_event, interval=0.5):
    seen = {}
    while not stop_event.is_set():
        try:
            with os.scandir(path) as it:
                for entry in it:
                    if entry.is_file():
                        p = entry.path
                        try:
                            mtime = entry.stat().st_mtime
                        except FileNotFoundError:
                            continue
                        if p not in seen or seen[p] != mtime:
                            seen[p] = mtime
                            q.put(p)
        except FileNotFoundError:
            pass
        time.sleep(interval)


def main(path='.'):
    q = Queue()
    workers = []
    for i in range(max(1, cpu_count() - 1)):
        p = Process(target=worker_loop, args=(q,))
        p.daemon = True
        p.start()
        workers.append(p)
    stop_event = Event()
    poller = Thread(target=poll_dir, args=(path, q, stop_event))
    poller.daemon = True
    poller.start()
    print(f"Watching {path} ... workers: {len(workers)}")
