#!/usr/bin/env python3
import sys, json, re

def extract(html):
    m = re.search('<title[^>]*>(.*?)</title>', html, re.IGNORECASE|re.S)
    combined = m.group(1).strip() if m else ''
    artist = None
    title = None
    if combined:
        for sep in [' - ', ' – ', ' — ', ' | ']:
            if sep in combined:
                a, t = combined.split(sep, 1)
                artist = a.strip()
                title = t.strip()
                break
        if title is None:
            title = combined
    return artist, title


def main():
    if len(sys.argv) > 1:
        path = sys.argv[1]
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            html = f.read()
    else:
        import glob
        files = sorted(glob.glob('*.html'))
        if not files:
            print(json.dumps({'artist': None, 'title': None}))
            return
        with open(files[0], 'r', encoding='utf-8', errors='ignore') as f:
            html = f.read()
    artist, title = extract(html)
    print(json.dumps({'artist': artist, 'title': title}))

if __name__ == '__main__':
    main()
