#!/usr/bin/env python3
import json, sys, argparse
from collections import defaultdict


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('input', nargs='?', default='-')
    parser.add_argument('--by', default=None, help='Key to group by (dot notation for nested keys)')
    parser.add_argument('--out', default='summary.txt')
    args = parser.parse_args()

    if args.input == '-':
        data = json.load(sys.stdin)
    else:
        with open(args.input) as f:
            data = json.load(f)

    if not isinstance(data, list):
        print('Input JSON must be a list of dictionaries', file=sys.stderr)
        sys.exit(2)

    by_key = args.by
    if by_key is None:
        common = None
        for item in data:
            if not isinstance(item, dict):
                common = set()
                break
            keys = set(item.keys())
            if common is None:
                common = keys
            else:
                common &= keys
            if not common:
                break
        if common:
            by_key = sorted(list(common))[0]
        else:
            print('No common key found across items; please specify --by KEY')
            sys.exit(1)

    groups = defaultdict(list)
    for item in data:
        if not isinstance(item, dict):
            continue
        keys = by_key.split('.')
        val = item
        for k in keys:
            if isinstance(val, dict) and k in val:
                val = val[k]
            else:
                val = None
                break
        groups[val].append(item)

    with open(args.out, 'w') as out:
        print('Grouping by:', by_key, file=out)
        for k in sorted(groups.keys(), key=lambda x: (x is None, x)):
            items = groups[k]
            print('Group:', k, 'Count:', len(items), file=out)
            if items:
                import json as _json
                print('  Sample item:', _json.dumps(items[0], ensure_ascii=False), file=out)
    print('Summary written to', args.out)

if __name__ == '__main__':
    main()
