import os
from sqlalchemy import create_engine, MetaData, Table, update


def main():
    db_url = os.environ.get('DB_URL')
    if not db_url:
        raise SystemExit('Set DB_URL environment variable, e.g., postgresql://user:pass@host/db')
    engine = create_engine(db_url)
    metadata = MetaData()
    metadata.reflect(bind=engine)

    A = Table('table_a', metadata, autoload_with=engine)
    B = Table('table_b', metadata, autoload_with=engine)

    a_cols = set(A.c.keys())
    b_cols = set(B.c.keys())
    update_cols = [c for c in (a_cols & b_cols) if c != 'id']
