import re, sys

# Translate a simple C for header to Python for-loop header
# Example: for (int i = 0; i < n; i++)  ->  for i in range(0, n, 1):

def translate_for_header(header):
    parts = [p.strip() for p in header.split(';')]
    if len(parts) != 3:
        return None
    init, cond, incr = parts

    m = re.match(r'(?:int\s+)?([A-Za-z_]\w*)\s*=\s*(.+)', init)
    if not m:
        return None
    var = m.group(1)
    start = m.group(2).strip()

    m2 = re.match(r'\s*' + re.escape(var) + r'\s*(<|<=|>|>=)\s*(.+)\s*$', cond)
    if not m2:
        return None
    op, limit = m2.group(1), m2.group(2).strip()

    stop = None
    step = None
    if op in ('<','<='):
        if op == '<':
            stop = limit
        else:
            if re.match(r'^\d+$', limit):
                stop = str(int(limit) + 1)
            else:
                stop = limit
        step = '1'
    elif op in ('>','>='):
        if op == '>':
            stop = limit
        else:
            if re.match(r'^\d+$', limit):
                stop = str(int(limit) - 1)
            else:
                stop = limit
        step = '-1'
    else:
        return None

    # Try to parse increment pattern from incr (e.g., i += 2 or i -= 3)
    m_incr = re.match(r'\s*([A-Za-z_]\w*)\s*([+-]=)\s*(\d+)\s*$', incr)
    if m_incr:
        incr_var = m_incr.group(1)
        delta_op = m_incr.group(2)
        delta = int(m_incr.group(3))
        if incr_var != var:
            return None
        if delta_op == '+=':
            step = str(delta)
        else:
            step = str(-delta)

    # Special-case: for i in range(n) style when start == '0' and step == '1'
    # and the stop bound equals the limit in the header (i < limit)
    if start == '0' and step == '1' and stop == limit:
        return f"for {var} in range({stop}):"

    return f"for {var} in range({start}, {stop}, {step})"


def translate_file(path):
    with open(path, 'r') as f:
        data = f.read()
    m_header = re.search(r'for\s*\(\s*(.*?)\s*\)', data, re.S)
    if not m_header:
        return None
    header = m_header.group(1)
    return translate_for_header(header)


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('# usage: python translator.py <cfile>')
        sys.exit(1)
    path = sys.argv[1]
    pyfor = translate_file(path)
    if pyfor:
        print(pyfor)
    else:
        print('# translation not possible for given C for loop')
