      "keystrokes": "cat > detect_encoding.py <<'PY'
#!/usr/bin/env python3
import sys
import argparse

# Try to import chardet if available
try:
    import chardet
except Exception:
    chardet = None


def detect_encoding(data):
    enc = None
    conf = 0.0

    # Prefer chardet's guess if available
    if chardet:
        try:
            r = chardet.detect(data)
            enc = r.get('encoding')
            conf = r.get('confidence', 0.0)
        except Exception:
            enc = None

    if enc:
        return enc, conf

    # Fallback: try UTF-8 decoding
    try:
        data.decode('utf-8')
        return 'utf-8', 0.99
    except UnicodeDecodeError:
        pass

    # Final fallback: latin-1 (ISO-8859-1) always decodes
    return 'latin-1', 0.50


def main():
    parser = argparse.ArgumentParser(description="Detect encoding of given bytes.")
    parser.add_argument('path', nargs='?', help='Path to file to read. If omitted, read from stdin.')
    args = parser.parse_args()

    if args.path:
        with open(args.path, 'rb') as f:
            data = f.read()
    else:
        data = sys.stdin.buffer.read()

    enc, conf = detect_encoding(data)
    print(f"{enc} (confidence={conf:.2f})")


if __name__ == '__main__':
    main()
PY
