#!/usr/bin/env python3
import json
import argparse


def bilinear_interp(grid, x, y):
    if not grid or not grid[0]:
        raise ValueError('Empty grid')
    h = len(grid)
    w = len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError('Non-rectangular grid')
    if x < 0 or x > w-1 or y < 0 or y > h-1:
        raise ValueError('Point outside grid')
    x0 = int(x)
    x1 = min(x0 + 1, w-1)
    y0 = int(y)
    y1 = min(y0 + 1, h-1)
    q11 = grid[y0][x0]
    q21 = grid[y0][x1]
    q12 = grid[y1][x0]
    q22 = grid[y1][x1]
    fx = x - x0
    fy = y - y0
    r1 = q11*(1.0 - fx) + q21*fx
    r2 = q12*(1.0 - fx) + q22*fx
    return r1*(1.0 - fy) + r2*fy


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--array', type=str, default=None, help='JSON 2D array')
    parser.add_argument('--x', type=float, default=None, help='x coordinate (column index)')
    parser.add_argument('--y', type=float, default=None, help='y coordinate (row index)')
    args = parser.parse_args()
    if args.array is None:
        grid = [[1,2,3],[4,5,6],[7,8,9]]
        x = 1.5
        y = 1.2
    else:
        grid = json.loads(args.array)
        if args.x is None or args.y is None:
            raise SystemExit('Please provide --x and --y with --array')
        x = args.x
        y = args.y
    val = bilinear_interp(grid, x, y)
    print(val)

if __name__ == '__main__':
    main()
