def climb_stairs(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 1, 1
    i = 2
    while i <= n:
        a, b = b, a + b
        i += 1
    return b


def main():
    if len(sys.argv) >= 2:
        try:
            n = int(sys.argv[1])
        except ValueError:
            print('Usage: python3 iterative_stairs.py N')
            return
        print(climb_stairs(n))
    else:
        print('Usage: python3 iterative_stairs.py N')

if __name__ == '__main__':
    main()
