from flask import Flask, request, jsonify

app = Flask(__name__)

class SmartService:
    def echo(self, message):
        return 'smart: ' + str(message)

@app.route('/amf', methods=['POST'])
def amf():
    payload = request.get_json(force=True, silent=True)
    if payload is None:
        payload = {}
    service_name = payload.get('service', 'SmartService')
    method = payload.get('method', 'echo')
    params = payload.get('params', [])
    if service_name == 'SmartService':
        svc = SmartService()
    else:
        return jsonify({'error': 'unknown service'}), 400
    if not hasattr(svc, method):
        return jsonify({'error': 'unknown method'}), 400
    fn = getattr(svc, method)
    try:
        result = fn(*params)
        return jsonify({'service': service_name, 'method': method, 'result': result})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)
PY
