import cv2
import sys
import os


def main(img_path):
    # Load cascades from OpenCV data path for reliability
    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    eye_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_eye.xml')

    img = cv2.imread(img_path)
    if img is None:
        print('ERROR: image not found:', img_path)
        return

    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

    # Detect faces in the whole image first
    faces = face_cascade.detectMultiScale(
        gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
    )

    for (x, y, w, h) in faces:
        # ROI for eyes within the detected face
        roi_gray = gray[y:y+h, x:x+w]
        eyes = eye_cascade.detectMultiScale(
            roi_gray, scaleFactor=1.1, minNeighbors=5, minSize=(15, 15)
        )
        for (ex, ey, ew, eh) in eyes:
            cv2.rectangle(img, (x+ex, y+ey), (x+ex+ew, y+ey+eh), (0, 255, 0), 2)
        # Optional: draw a rectangle around the face as well
        cv2.rectangle(img, (x, y), (x+w, y+h), (255, 0, 0), 2)

    out = 'output_' + os.path.basename(img_path)
    cv2.imwrite(out, img)
    print('done', out)


if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else '')
PY
