# Pure-Python ndmin demonstration (no numpy)
from typing import Any

def depth(a: Any) -> int:
    if isinstance(a, list) and a:
        return 1 + max(depth(x) for x in a)
    elif isinstance(a, list) and not a:
        return 1
    else:
        return 0

def wrap_ndmin(a, ndmin):
    d = depth(a)
    diff = max(0, ndmin - d)
    out = a
    for _ in range(diff):
        out = [out]
    return out

def shape_of(x):
    if not isinstance(x, list):
        return []
    if not x:
        return [0]
    return [len(x)] + shape_of(x[0])

def show(a, ndmin):
    arr = wrap_ndmin(a, ndmin)
    print("a=", a, "ndmin=", ndmin, "=> shape:", shape_of(arr), "array=\n", arr)

