import os
import scrapy
from scrapy import FormRequest

class SoLoginSpider(scrapy.Spider):
    name = 'so_login'
    allowed_domains = ['stackoverflow.com']
    start_urls = ['https://stackoverflow.com/users/login']

    def parse(self, response):
        # Stack Overflow login page contains a CSRF token in a field named fkey
        fkey = response.css('input[name="fkey"]::attr(value)').get()
        if not fkey:
            self.logger.error('fkey CSRF token not found on login page')
            return
        data = {
            'fkey': fkey,
            'email': os.environ.get('SO_EMAIL',''),
            'password': os.environ.get('SO_PASSWORD','')
        }
        # Submit login form
        yield FormRequest.from_response(response, formdata=data, callback=self.after_login)

    def after_login(self, response):
        if 'logout' in response.text.lower() or 'Sign out' in response.text:
            self.logger.info('Login appears successful')
            # Optionally visit home to confirm access
            yield scrapy.Request('https://stackoverflow.com/', callback=self.after_login_success)
        else:
            self.logger.warning('Login may have failed; no logout indicator found')

    def after_login_success(self, response):
        # Simple confirmation page content check
        if 'Stack Overflow' in response.text:
            self.logger.info('Access after login confirmed')
        else:
            self.logger.warning('Could not confirm access after login')
