#!/usr/bin/env python3
import tkinter as tk
from tkinter import ttk

def on_item_activated(tree):
    item = tree.focus()
    if not item:
        return
    values = tree.item(item, 'values')
    print(f'Activated item: {item} {values}')

def main():
    root = tk.Tk()
    root.title('Treeview Button Row')
    tree = ttk.Treeview(root, columns=('Name','Action'), show='headings', selectmode='browse')
    for c in ('Name','Action'):
        tree.heading(c, text=c)
        tree.column(c, width=120)

    items = [('Open','Run'), ('Save','Disk'), ('Delete','Row')]
    for i,(n,a) in enumerate(items):
        tree.insert('', 'end', iid=f'item{i}', values=(n,a))

    def _on_double_click(event):
        region = tree.identify('region', event.x, event.y)
        if region in ('cell','tree'):
            on_item_activated(tree)

    tree.bind('<Double-1>', _on_double_click)
    tree.pack(fill='both', expand=True)
    root.mainloop()

if __name__ == '__main__':
    main()
