package com.example.phishguard
object PhishDetector {
  fun analyze(url: String): Pair<Boolean, String> {
    if (url.isBlank()) return Pair(true, "Empty URL")
    val domain = url.removePrefix("http://").removePrefix("https://").substringAfter("//").substringBefore("/")
    val suspicious = domain.contains("pay", ignoreCase = true) || domain.startsWith("secure", ignoreCase = true)
    val reason = if (suspicious) "This site imitates a trusted brand" else "URL appears benign (heuristic)"
    return Pair(suspicious, reason)
  }
}
