import Foundation

struct WatchIdentity: Codable {
    let brand: String
    let model: String
    let classification: String
    let price: Double?
}

class ApiClient {
    static let shared = ApiClient()
    private init() {}

    func identifyWatch(imageData: Data, completion: @escaping (WatchIdentity?, Error?) -> Void) {
        guard let url = URL(string: "https://your.api/base/watch/identify") else {
            completion(nil, nil)
            return
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/octet-stream", forHTTPHeaderField: "Content-Type")

        let task = URLSession.shared.uploadTask(with: request, from: imageData) { data, response, error in
            if let data = data {
                do {
                    let decoder = JSONDecoder()
                    let identity = try decoder.decode(WatchIdentity.self, from: data)
                    completion(identity, nil)
                } catch {
                    completion(nil, error)
                }
            } else {
                completion(nil, error)
            }
        }
        task.resume()
    }
}
