#!/usr/bin/env python3
import os

RPZ_PATH = '/app/pdns/rpz.zone'
FEED_PATH = '/app/feeds/cti_feed.txt'


def main():
    existing = set()
    if os.path.exists(RPZ_PATH):
        with open(RPZ_PATH, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split()
                if len(parts) >= 5 and parts[1] == '60' and parts[2] == 'IN' and parts[3] == 'A':
                    existing.add(parts[0])
    domains = []
    if os.path.exists(FEED_PATH):
        with open(FEED_PATH, 'r') as f:
            domains = [line.strip() for line in f if line.strip()]
    if not domains:
        domains = ['cti.blocked.example.com', 'malware.cti.example']

    added = []
    for d in domains:
        dn = d.rstrip('.') + '.'
        if dn not in existing:
            added.append(dn)
            existing.add(dn)
    if added:
        with open(RPZ_PATH, 'a') as rpz:
            rpz.write('\n# CTI ingested entries (dedup)\n')
            for dn in added:
                rpz.write(f'{dn} 60 IN A 0.0.0.0\n')
        print('CTI ingestion appended', len(added), 'new entries')
    else:
        print('CTI ingestion: no new entries to append')

if __name__ == '__main__':
    main()
