from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
import logging
import os
import datetime

# Lightweight logging setup
os.makedirs("logs", exist_ok=True)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def map_hubspot_to_bigcommerce(payload: dict):
    email = payload.get("email") if isinstance(payload, dict) else None
    first = payload.get("first_name") or payload.get("firstname")
    last = payload.get("last_name") or payload.get("lastname")
    transformed = {
        "email": email,
        "first_name": first,
        "last_name": last,
        "custom_fields": payload.get("custom_properties", {}) if isinstance(payload, dict) else {}
    }
    return transformed

def log_mapping(mapped: dict):
    try:
        with open("logs/webhook.log", "a") as f:
            f.write(f"{datetime.datetime.utcnow().isoformat()} {mapped}\n")
    except Exception as e:
        logger.error("Failed to write webhook mapping log: %s", e)

app = FastAPI()

@app.get("/")
def read_root():
    return {"status": "ok"}

@app.get("/health")
def health():
    return {"status": "healthy"}

@app.post("/webhook/hubspot")
async def hubspot_webhook(req: Request):
    try:
        payload = await req.json()
    except Exception:
        return JSONResponse(status_code=400, content={"error": "invalid_json"})

    mapped = map_hubspot_to_bigcommerce(payload)
    log_mapping(mapped)
    logger.info("HubSpot webhook received payload_size=%d mapped=%s", len(str(payload)), mapped)
    return {"received": True, "type": "hubspot_webhook", "payload_size": len(str(payload)), "mapped": mapped}
