        add_action( 'init', array( $this, 'register_post_type_fs_job' ) );
        add_action( 'rest_api_init', array( $this, 'register_fs_rest_routes' ) );
    }

    public function register_post_type_fs_job() {
        $labels = array(
            'name' => __( 'Field Service Jobs', 'field-service-scheduler' ),
            'singular_name' => __( 'Field Service Job', 'field-service-scheduler' ),
            'menu_name' => __( 'Field Scheduler', 'field-service-scheduler' ),
        );
        $args = array(
            'labels' => $labels,
            'public' => true,
            'has_archive' => true,
            'rewrite' => array( 'slug' => 'fs-jobs' ),
            'supports' => array( 'title', 'editor', 'custom-fields' ),
            'show_in_rest' => true,
        );
        register_post_type( 'fs_job', $args );
    }

    public function register_fs_rest_routes() {
        register_rest_route( 'fs/v1', '/jobs', array(
            'methods' => WP_REST_Server::READABLE,
            'callback' => array( $this, 'rest_get_jobs' ),
            'permission_callback' => '__return_true',
        ) );
    }

    public function rest_get_jobs( $request ) {
        $args = array(
            'post_type' => 'fs_job',
            'posts_per_page' => 10
        );
        $query = new WP_Query( $args );
        $data = array();
        foreach ( $query->posts as $post ) {
            $data[] = array(
                'id' => $post->ID,
                'title' => $post->post_title,
                'status' => get_post_status( $post->ID ),
                'url' => get_permalink( $post->ID ),
            );
        }
        return rest_ensure_response( $data );
    }
}

new Field_Service_Scheduler();
