app = FastAPI(title="AI Travel Engine - Prototype")

class TravelItem(BaseModel):
    id: str
    provider: str
    type: str
    name: str
    price: float
    currency: str = "USD"
    rating: float = 0.0
    availability: int = 0
    attributes: Dict = {}

SAMPLE_DATA = [
    {"id":"f1","provider":"Amadeus","type":"flight","name":"Flight A123","price":199.0,"rating":4.5,"availability":5,"attributes":{"airline":"AA","stops":1}},
    {"id":"f2","provider":"Sabre","type":"flight","name":"Flight B456","price":249.0,"rating":4.7,"availability":3,"attributes":{"airline":"DL","stops":0}},
    {"id":"h1","provider":"Expedia","type":"hotel","name":"Hotel Luxe","price":150.0,"rating":4.3,"availability":10,"attributes":{"stars":5}},
    {"id":"c1","provider":"Booking","type":"car","name":"Compact Car","price":40.0,"rating":4.1,"availability":6,"attributes":{"transmission":"automatic"}}
]

# AI weights and data (will be overridden by config.yaml if present)
ai_weights = {"price": 0.6, "rating": 0.3, "availability": 0.1}

def load_config():
    global ai_weights
    try:
        with open("config.yaml", "r") as f:
            cfg = yaml.safe_load(f) or {}
            w = cfg.get("ai_weights")
            if isinstance(w, dict):
                ai_weights = w
    except Exception:
        pass

def score_item(item: TravelItem, context: dict) -> float:
    w = ai_weights
    score = 0.0
    score += w.get("price", 0.5) * (100.0 - item.price)
    score += w.get("rating", 0.3) * (item.rating / 5.0 * 100.0)
    score += w.get("availability", 0.1) * (min(item.availability, 10) / 10 * 100.0)
    if context.get("preferred_type") == item.type:
        score += 5.0
    max_price = context.get("max_price")
    if max_price is not None and item.price <= float(max_price):
        score += 2.0
    return score

@app.get("/search/{query_type}")
def search(query_type: str, q: Optional[str] = None, max_price: Optional[float] = None) -> dict:
    load_config()
    items = [TravelItem(**d) for d in SAMPLE_DATA if d["type"] == query_type]
    results = sorted(items, key=lambda it: score_item(it, {"max_price": max_price}), reverse=True)
    max_p = max((it.price for it in items), default=0.0)
    return {"query": {"type": query_type, "q": q}, "results": [it.dict() for it in results], "max_price": max_p}

@app.get("/admin/config")
def get_config():
    try:
        with open("config.yaml","r") as f:
            return yaml.safe_load(f)
    except Exception as e:
        return {"error": str(e)}

@app.post("/admin/config")
def update_config(payload: dict):
    global ai_weights
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="payload must be a dict")
    if "ai_weights" in payload and isinstance(payload["ai_weights"], dict):
        ai_weights = payload["ai_weights"]
        cfg = {"ai_weights": ai_weights}
        with open("config.yaml","w") as f:
            yaml.safe_dump(cfg, f)
        return {"status": "updated", "ai_weights": ai_weights}
    return {"status": "no_changes"}

@app.get("/")
def root():
    return {"status": "AI Travel Engine prototype running"}
