from fastapi import FastAPI
from pydantic import BaseModel
import sqlite3
import os

app = FastAPI()
DB_PATH = os.path.join('infra','database.db')

class SensorEvent(BaseModel):
    sensor_id: str
    timestamp: float
    motion: bool
    latency_ms: int = 0


def init_db():
    os.makedirs('infra', exist_ok=True)
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute(
        '''CREATE TABLE IF NOT EXISTS events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sensor_id TEXT,
            timestamp REAL,
            motion INTEGER,
            latency_ms INTEGER
        )'''
    )
    conn.commit()
    conn.close()

@app.on_event('startup')
def startup():
    init_db()

@app.post('/sensor/{sensor_id}/events')
def post_event(sensor_id: str, event: SensorEvent):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute(
        'INSERT INTO events (sensor_id, timestamp, motion, latency_ms) VALUES (?, ?, ?, ?)',
        (sensor_id, event.timestamp, int(event.motion), event.latency_ms)
    )
    conn.commit()
    conn.close()
    return {'status': 'ok'}
