#!/usr/bin/env python3
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import uuid
from urllib.parse import urlparse, parse_qs

APPOINTMENTS = {}

class Handler(BaseHTTPRequestHandler):
    def _set_json(self, data, code=200):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def do_POST(self):
        length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(length).decode('utf-8') if length > 0 else '{}'
        try:
            data = json.loads(body)
        except Exception:
            data = {}
        path = self.path
        if path == '/book':
            appt_id = str(uuid.uuid4())
            appt = {
                'id': appt_id,
                'patient': data.get('patient'),
                'time': data.get('time'),
                'service': data.get('service','general'),
                'status': 'scheduled'
            }
            APPOINTMENTS[appt_id] = appt
            self._set_json({'appointment_id': appt_id, 'status': 'scheduled', 'details': appt})
        elif path == '/reschedule':
            appt_id = data.get('appointment_id')
            new_time = data.get('new_time')
            if not appt_id or appt_id not in APPOINTMENTS:
                self._set_json({'error':'invalid_id'}, 400)
            else:
                appt = APPOINTMENTS[appt_id]
                appt['time'] = new_time
                appt['status'] = 'rescheduled'
                self._set_json({'appointment_id': appt_id, 'status': 'rescheduled', 'details': appt})
        elif path == '/cancel':
            appt_id = data.get('appointment_id')
            if not appt_id or appt_id not in APPOINTMENTS:
                self._set_json({'error':'invalid_id'}, 400)
            else:
                APPOINTMENTS.pop(appt_id)
                self._set_json({'appointment_id': appt_id, 'status': 'cancelled'})
        else:
            self._set_json({'error':'unknown_endpoint'}, 404)

    def do_GET(self):
        if self.path.startswith('/faq'):
            q = parse_qs(urlparse(self.path).query).get('q', [''])[0]
            if 'What time do you open on Friday' in q:
                self._set_json({'answer':'We open at 8:00 AM on Friday.'})
            else:
                self._set_json({'faq': [
                    {'question': 'What are clinic hours?', 'answer': '8am-5pm Mon-Fri'},
                    {'question': 'Do you accept new patients?', 'answer': 'Yes, we accept new patients.'},
                    {'question': 'How do I reschedule?', 'answer': 'Use the /book or /reschedule endpoints.'}
                ]})
        else:
            self._set_json({'error':'unknown_endpoint'}, 404)


def run(server_class=HTTPServer, handler_class=Handler, port=8000):
    httpd = server_class(('', port), handler_class)
    print('Serving HTTP on port', port)
    httpd.serve_forever()

if __name__ == '__main__':
    run()
