import express from 'express';
import dotenv from 'dotenv';
import crypto from 'crypto';

dotenv.config();

type PaymentRecord = {
  order_id: string;
  amount: number;
  currency: string;
  hosted_link?: string;
  created_at: string;
  status?: string;
  txHash?: string;
};

const app = express();
app.use(express.json());

// In-memory store for demo purposes
const payments = new Map<string, PaymentRecord>();
const SUPPORTED = new Set(['RLUSD', 'USDC']);
const HOSTED_BASE = process.env.XRPL_HOSTED_BASE || 'https://xrpl-checkout.example';

app.get('/', (req, res) => {
  res.send('Shopify XRPL Skeleton running');
});

app.get('/health', (_req, res) => res.json({ ok: true }));

// Create a hosted XRPL payment link (demo implementation)
app.post('/pay-with-xrpl', (req, res) => {
  const { order_id, amount, currency } = req.body;
  if (!order_id || typeof amount !== 'number' || !currency) {
    return res.status(400).json({ error: 'order_id, amount, and currency are required' });
  }
  if (!SUPPORTED.has(currency)) {
    return res.status(400).json({ error: 'Unsupported currency' });
  }
  const hosted_link = `${HOSTED_BASE}/checkout?order_id=${encodeURIComponent(order_id)}&amount=${amount}&currency=${currency}`;
  const rec: PaymentRecord = {
    order_id,
    amount,
    currency,
    hosted_link,
    created_at: new Date().toISOString(),
    status: 'pending'
  };
  payments.set(order_id, rec);
  res.json({ hosted_link, order_id });
});

// Webhook endpoint to confirm on-chain payment (demo, does not enforce real signature verification here)
app.post('/webhook/xrpl', (req, res) => {
  const payload = req.body || {};
  const order_id = payload.order_id;
  if (!order_id) return res.status(400).json({ error: 'order_id required' });
  const rec = payments.get(order_id) || { order_id, amount: payload.amount ?? 0, currency: payload.currency ?? 'RLUSD', created_at: new Date().toISOString() };
  if (payload.status) rec.status = payload.status;
  if (payload.txHash) rec.txHash = payload.txHash;
  payments.set(order_id, rec);
  res.json({ ok: true, order_id });
});

// Status endpoint
app.get('/status/:order_id', (req, res) => {
  const order_id = req.params.order_id;
  const rec = payments.get(order_id);
  if (!rec) return res.status(404).json({ error: 'not found' });
  res.json(rec);
});

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server listening on http://localhost:${port}`);
});
