                good = True
                for j in range(len(new_b)-1):
                    if new_b[j] > new_b[j+1]:
                        good = False
                        break

                if good:
                    found = True

            # Try removing a[break_pos+1]
            if not found and break_pos+1 < n:
                new_a = a[:break_pos+1] + a[break_pos+2:]
