def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    cubes = list(map(int, data[1:]))

    # Count frequency of each number
    from collections import Counter
    freq = Counter(cubes)

    # Sort numbers by frequency (ascending) - distribute rare numbers first
    numbers_by_freq = sorted(freq.keys(), key=lambda x: freq[x])

    heap1 = []
    heap2 = []

    # Greedy distribution: try to balance heaps while maximizing diversity
    for num in numbers_by_freq:
        count = freq[num]
        for i in range(count):
            if len(heap1) < len(heap2):
                heap1.append(num)
            else:
                heap2.append(num)

    # Ensure both heaps have exactly n elements
    while len(heap1) > n:
        heap2.append(heap1.pop())
    while len(heap2) > n:
        heap1.append(heap2.pop())

    # Calculate number of distinct 4-digit numbers
    distinct_numbers = set()
    for a in heap1:
        for b in heap2:
            distinct_numbers.add(a * 100 + b)

    # Create assignment array
    assignment = []
    num_to_heap = {}
    for i, num in enumerate(heap1):
        num_to_heap.setdefault(num, []).append((i, 1))
    for i, num in enumerate(heap2):
        num_to_heap.setdefault(num, []).append((i, 2))

    # Map each original cube to its heap
    for num in cubes:
        if num in num_to_heap and num_to_heap[num]:
            assignment.append(num_to_heap[num].pop()[1])
        else:
            assignment.append(1 if len(heap1) < n else 2)

    print(len(distinct_numbers))
    print(' '.join(map(str, assignment)))

if __name__ == '__main__':
    solve()
