def solve():
    import sys

    # Read input
    line = sys.stdin.readline().strip()
    if not line:
        return

    a, b, k = map(int, line.split())

    # Sieve of Eratosthenes to find primes up to b
    max_n = b
    is_prime = [True] * (max_n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(max_n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, max_n + 1, i):
                is_prime[j] = False

    # Create prefix sum of prime counts
    prime_prefix = [0] * (b + 2)
    for i in range(1, b + 1):
        prime_prefix[i] = prime_prefix[i - 1] + (1 if is_prime[i] else 0)

    # Function to count primes in [l, r]
    def count_primes(l, r):
        return prime_prefix[r] - prime_prefix[l - 1]

    # Binary search for minimum l
    left, right = 1, b - a + 1
    answer = -1

    while left <= right:
        mid = (left + right) // 2

        # Check if every window of length mid has at least k primes
        valid = True
        for start in range(a, b - mid + 2):
            if count_primes(start, start + mid - 1) < k:
                valid = False
                break

        if valid:
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    print(answer)

if __name__ == "__main__":
    solve()
